def remove_duplicates(xml_data):
    tree = ET.fromstring(xml_data)
    nums = [int(child.text) for child in tree.findall('.//num')]
    unique_nums = list(set(nums))
    for num in unique_nums:
        if nums.count(num) > 1 and num * 2 > 5:
            nums = list(filter(lambda x: x != num, nums))
    # Filter out duplicates whose sum is greater than 5
    unique_nums = []
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] > 5:
                if nums[i] not in unique_nums:
                    unique_nums.append(nums[i])
                if nums[j] not in unique_nums:
                    unique_nums.append(nums[j])
                break
        else:
            if nums[i] not in unique_nums:
                unique_nums.append(nums[i])
    return unique_nums
