[C++ code]
class LinkedList {
private:
    struct Node {
        int data;
        Node* next;
    };
    Node* head;
public:
    LinkedList() {
        head = nullptr;
    }
    void insert(int value) {
        Node* newNode = new Node;
        newNode->data = value;
        newNode->next = head;
        head = newNode;
    }
    void remove(int value) {
        Node* currNode = head;
        Node* prevNode = nullptr;
        while (currNode != nullptr) {
            if (currNode->data == value) {
                if (prevNode == nullptr) {
                    head = currNode->next;
                } else {
                    prevNode->next = currNode->next;
                }
                delete currNode;
                return;
            }
            prevNode = currNode;
            currNode = currNode->next;
        }
    }
};

