```swift
import UIKit
class WeatherTableViewController: UITableViewController {

    let apiURL = "https://api.openweathermap.org/data/2.5/forecast/daily?q=London&cnt=10&appid=YOUR_API_KEY"
    var weatherData = [Weather]()

    override func viewDidLoad() {
        super.viewDidLoad()

        // Fetch weather data from API
        guard let url = URL(string: apiURL) else {
            return
        }

        URLSession.shared.dataTask(with: url) { (data, response, error) in
            guard let data = data else {
                return
            }

            do {
                let decoder = JSONDecoder()
                decoder.keyDecodingStrategy = .convertFromSnakeCase
                let weatherResponse = try decoder.decode(WeatherResponse.self, from: data)
                self.weatherData = weatherResponse.list
                DispatchQueue.main.async {
                    self.tableView.reloadData()
                }
            } catch let error {
                print(error.localizedDescription)
            }
        }.resume()
    }

    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return weatherData.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "WeatherTableViewCell", for: indexPath) as! WeatherTableViewCell

        let weather = weatherData[indexPath.row]
        cell.dateLabel.text = weather.dt.formatDate()
        cell.temperatureLabel.text = "\(Int(weather.temp.day))°C"
        cell.humidityLabel.text = "\(weather.humidity)%"
        cell.pressureLabel.text = "\(weather.pressure) hPa"
        cell.windSpeedLabel.text = "\(weather.speed) m/s"
        cell.windDirectionLabel.text = weather.deg.getWindDirection()
        cell.uvIndexLabel.text = "\(weather.uvi)"
        cell.weatherImageView.image = UIImage(named: weather.weather[0].icon)

        return cell
    }

    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        let weather = weatherData[indexPath.row]
        let detailVC = WeatherDetailViewController(weather: weather)
        navigationController?.pushViewController(detailVC, animated: true)
    }
}
class WeatherTableViewCell: UITableViewCell {

    @IBOutlet weak var dateLabel: UILabel!
    @IBOutlet weak var temperatureLabel: UILabel!
    @IBOutlet weak var humidityLabel: UILabel!
    @IBOutlet weak var pressureLabel: UILabel!
    @IBOutlet weak var windSpeedLabel: UILabel!
    @IBOutlet weak var windDirectionLabel: UILabel!
    @IBOutlet weak var uvIndexLabel: UILabel!
    @IBOutlet weak var weatherImageView: UIImageView!
}
class WeatherDetailViewController: UIViewController {

    var weather: Weather

    init(weather: Weather) {
        self.weather = weather
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override func viewDidLoad() {
        super.viewDidLoad()

        view.backgroundColor = .white

        let stackView = UIStackView()
        stackView.axis = .vertical
        stackView.alignment = .center
        stackView.spacing = 10

        let dateLabel = UILabel()
        dateLabel.text = weather.dt.formatDate()
        stackView.addArrangedSubview(dateLabel)

        let temperatureLabel = UILabel()
        temperatureLabel.text = "\(Int(weather.temp.day))°C"
        stackView.addArrangedSubview(temperatureLabel)

        let humidityLabel = UILabel()
        humidityLabel.text = "Humidity: \(weather.humidity)%"
        stackView.addArrangedSubview(humidityLabel)

        let pressureLabel = UILabel()
        pressureLabel.text = "Pressure: \(weather.pressure) hPa"
        stackView.addArrangedSubview(pressureLabel)

        let windLabel = UILabel()
        windLabel.text = "Wind: \(weather.speed) m/s \(weather.deg.getWindDirection())"
        stackView.addArrangedSubview(windLabel)

        let uvIndexLabel = UILabel()
        uvIndexLabel.text = "UV Index: \(weather.uvi)"
        stackView.addArrangedSubview(uvIndexLabel)

        view.addSubview(stackView)
        stackView.translatesAutoresizingMaskIntoConstraints = false
        NSLayoutConstraint.activate([
            stackView.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            stackView.centerYAnchor.constraint(equalTo: view.centerYAnchor)
        ])
    }
}
extension Int {
    func getWindDirection() -> String {
        let directions = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]
        let index = Int((Double(self) / 45.0).rounded()) % 8
        return directions[index]
    }
}
extension TimeInterval {
    func formatDate() -> String {
        let dateFormatter = DateFormatter()
        dateFormatter.dateFormat = "EEEE, MMM d"
        let date = Date(timeIntervalSince1970: self)
        return dateFormatter.string(from: date)
    }
}
struct WeatherResponse: Codable {
