    let temp: Temperature
    let pressure: Int
    let humidity: Int
    let speed: Double
    let deg: Int
    let uvi: Double
    let weather: [WeatherCondition]

    enum CodingKeys: String, CodingKey {
        case dt
        case temp
        case pressure
        case humidity
        case speed
        case deg
        case uvi
        case weather
    }
}
struct Temperature: Codable {
