using Microsoft.ML;
using Microsoft.ML.Data;
// Define the input data class
public class CruiseData
{
    [LoadColumn(0)]
    public float Duration { get; set; }
    [LoadColumn(1)]
    public float Price { get; set; }
    [LoadColumn(2)]
    public float Rating { get; set; }
