    public float Age { get; set; }
    [LoadColumn(6)]
    public bool IsLuxury { get; set; }
    [LoadColumn(7)]
    public bool IsFamilyFriendly { get; set; }
}
// Define the output data class
public class CruisePrediction
{
    [ColumnName("PredictedLabel")]
    public bool IsRecommended { get; set; }
}
// Load the data
var mlContext = new MLContext();
var data = mlContext.Data.LoadFromTextFile<CruiseData>("cruise_data.csv", separatorChar: ',');
// Split the data into training and testing sets
var trainTestSplit = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
// Define the pipeline
var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", "IsRecommended")
    .Append(mlContext.Transforms.Concatenate("Features", "Duration", "Price", "Rating", "CabinSize", "Itinerary", "Age", "IsLuxury", "IsFamilyFriendly"))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("Label"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());
// Train the model
var model = pipeline.Fit(trainTestSplit.TrainSet);
// Evaluate the model
var predictions = model.Transform(trainTestSplit.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions);
// Use the model to make predictions
var predictionEngine = mlContext.Model.CreatePredictionEngine<CruiseData, CruisePrediction>(model);
var prediction = predictionEngine.Predict(new CruiseData { Duration = 7, Price = 5000, Rating = 4.5f, CabinSize = 300, Itinerary = 0.8f, Age = 50, IsLuxury = true, IsFamilyFriendly = false });
