                maxIndex = j
            }
        }
        importantDemands[i] = demandClusters[maxIndex][0]
        pr[maxIndex] = 0
    }
    // generate concise statement summarizing important demands and their relationships
    statement := "The most important demands are:"
    for _, demand := range importantDemands {
        statement += " " + demand + ","
    }
    statement = statement[:len(statement)-1] + "."
    return statement
}
