Sure! Here are a few other sorting algorithms that you can add to the analysis:
1. Insertion Sort:
```
function sorted = insertionSort(data)
    n = length(data);
    for i = 2:n
        key = data(i);
        j = i - 1;
        while j >= 1 && data(j) > key
            data(j+1) = data(j);
            j = j - 1;
        end
        data(j+1) = key;
    end
    sorted = data;
end
```
2. Selection Sort:
```
function sorted = selectionSort(data)
    n = length(data);
    for i = 1:n-1
        min_idx = i;
        for j = i+1:n
            if data(j) < data(min_idx)
                min_idx = j;
            end
        end
        temp = data(i);
        data(i) = data(min_idx);
        data(min_idx) = temp;
    end
    sorted = data;
end
```
3. Heap Sort:
```
function sorted = heapSort(data)
    n = length(data);
    % Build a max heap
    for i = floor(n/2):-1:1
        data = maxHeapify(data, i, n);
    end
    % Extract elements one by one
    for i = n:-1:2
        temp = data(1);
        data(1) = data(i);
        data(i) = temp;
        data = maxHeapify(data, 1, i-1);
    end
    sorted = data;
end
function data = maxHeapify(data, i, n)
    left = 2*i;
    right = 2*i + 1;
    largest = i;
    if left <= n && data(left) > data(largest)
        largest = left;
    end
    if right <= n && data(right) > data(largest)
        largest = right;
    end
    if largest ~= i
        temp = data(i);
        data(i) = data(largest);
        data(largest) = temp;
        data = maxHeapify(data, largest, n);
    end
end
```
