To generate three unique product ideas that encourage physical activity and education in children, while ensuring that no age group gets the same activity more than once and the interests do not repeat in any of the product ideas, we can use the following C# code:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
class Program
{
    static void Main(string[] args)
    {
        // Define lists of age groups and interests
        List<string> ageGroups = new List<string> { "3-5", "6-8", "9-12" };
        List<string> interests = new List<string> { "Sports", "Science", "Art", "Music" };
        // Shuffle the interests list randomly
        Random rnd = new Random();
        interests = interests.OrderBy(x => rnd.Next()).ToList();
        // Generate three unique product ideas
        for (int i = 1; i <= 3; i++)
        {
            Console.WriteLine("Product Idea " + i + ":");
            List<string> usedAgeGroups = new List<string>();
            List<string> usedInterests = new List<string>();
            for (int j = 0; j < ageGroups.Count; j++)
            {
                // Choose a random age group that hasn't been used yet
                string ageGroup;
                do
                {
                    ageGroup = ageGroups[rnd.Next(ageGroups.Count)];
                } while (usedAgeGroups.Contains(ageGroup));
                usedAgeGroups.Add(ageGroup);
                // Choose a random interest that hasn't been used yet
                string interest;
                do
                {
                    interest = interests[rnd.Next(interests.Count)];
                } while (usedInterests.Contains(interest));
                usedInterests.Add(interest);
                Console.WriteLine("- " + ageGroup + " year olds: " + interest);
            }
        }
    }
}
```
This code defines two lists, one for age groups and one for interests. It then shuffles the interests list randomly to ensure that they are not repeated in any of the product ideas. 
Next, it generates three unique product ideas by choosing a random age group and interest that haven't been used yet. It ensures that no age group gets the same activity more than once by keeping track of the used age groups in a separate list. 
Finally, it prints out the product ideas with their corresponding age groups and interests. The output might look something like this:
