import javax.swing.text.*;
import javax.swing.text.html.*;
import java.awt.*;
public class LinkColorChanger {
    public static void changeLinkColor(Document doc, Color color) {
        if (doc instanceof HTMLDocument) {
            HTMLDocument htmlDoc = (HTMLDocument) doc;
            ElementIterator iterator = new ElementIterator(htmlDoc);
            Element element;
            while ((element = iterator.next()) != null) {
                AttributeSet attrs = element.getAttributes();
                Object name = attrs.getAttribute(HTML.Tag.A);
                if (name instanceof SimpleAttributeSet) {
                    SimpleAttributeSet attr = (SimpleAttributeSet) name;
                    attr.addAttribute(HTML.Attribute.COLOR, color.toString());
                }
            }
        }
    }
}
