To analyze GDP data and identify the country with the highest consistent growth in the last five years, you can use Java code to read and process the data from a CSV file or a database. Here is an example Java code that reads GDP data from a CSV file and identifies the country with the highest consistent growth in the last five years:
```
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
public class GDPAnalyzer {
    public static void main(String[] args) {
        String csvFile = "gdp_data.csv";
        String line = "";
        String cvsSplitBy = ",";
        double highestGrowthRate = 0;
        String highestGrowthCountry = "";
        try (BufferedReader br = new BufferedReader(new FileReader(csvFile))) {
            // Skip the header line
            br.readLine();
            while ((line = br.readLine()) != null) {
                // Split the line by comma
                String[] data = line.split(cvsSplitBy);
                // Calculate the growth rate for the last five years
                double growthRate = (Double.parseDouble(data[4]) - Double.parseDouble(data[0])) / Double.parseDouble(data[0]);
                // Check if this country has the highest consistent growth rate
                if (growthRate > highestGrowthRate) {
                    highestGrowthRate = growthRate;
                    highestGrowthCountry = data[1];
                }
            }
            System.out.println("The country with the highest consistent growth rate in the last five years is " + highestGrowthCountry + " with a growth rate of " + highestGrowthRate);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```
