// Function to check if a number is prime
function isPrime(num) {
  if (num <= 1) return false;
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) return false;
  }
  return true;
}
// Function to calculate the sum of digits
function sumOfDigits(num) {
  let sum = 0;
  while (num) {
    sum += num % 10;
    num = Math.floor(num / 10);
  }
  return sum;
}
// Function to calculate the product of digits
function productOfDigits(num) {
  let product = 1;
  while (num) {
    product *= num % 10;
    num = Math.floor(num / 10);
  }
  return product;
}
// Function to filter prime numbers based on user-specified constraints
function filterPrimes(rangeStart, rangeEnd, sumConstraint, productConstraint, positionConstraint) {
  let primes = [];
  for (let i = rangeStart; i <= rangeEnd; i++) {
    if (isPrime(i)) {
      if (sumConstraint && sumOfDigits(i) !== sumConstraint) continue;
      if (productConstraint && productOfDigits(i) !== productConstraint) continue;
      if (positionConstraint && positionConstraint !== i.toString().indexOf(positionConstraint)) continue;
      primes.push(i);
    }
  }
  return primes;
}
// Function to sort an array in descending order using a custom sorting function
function sortDescending(arr, compareFn) {
  return arr.sort((a, b) => compareFn(b, a));
}
