            var sentence = "I'm going to be the best doctor IN the country one day.";
            var annotation = new Annotation(sentence);
            pipeline.annotate(annotation);
            // Evaluate the sentence for grammar and punctuation
            var sentences = annotation.get(new CoreAnnotations.SentencesAnnotation().getClass()) as ArrayList;
            var tokens = sentences[0].get(new CoreAnnotations.TokensAnnotation().getClass()) as ArrayList;
            var lastToken = tokens[tokens.Count - 1] as CoreLabel;
            var lastWord = lastToken.word();
            var punctuation = lastWord[lastWord.Length - 1];
            if (Char.IsPunctuation(punctuation))
            {
                Console.WriteLine("The sentence ends with punctuation.");
            }
            else
            {
                Console.WriteLine("The sentence does not end with punctuation.");
            }
        }
    }
}
