```
% Define the two input signals
x = [1, 2, 3, 4, 5];
h = [5, 4, 3, 2, 1];
% Determine the length of the input signals
N = length(x);
M = length(h);
% Initialize the output signal
y = zeros(1, N + M - 1);
% Perform the convolution using nested loops
for n = 1:N+M-1
    for k = max(1, n-M+1):min(n, N)
        y(n) = y(n) + x(k) * h(n-k+1);
    end
end
% Display the output signal
disp(y);
