class LinearRegression {
    var slope: Double
    var intercept: Double

    init(slope: Double, intercept: Double) {
        self.slope = slope
        self.intercept = intercept
    }

    func predict(x: Double) -> Double {
        return slope * x + intercept
    }

    func train(x: [Double], y: [Double]) {
        let n = Double(x.count)
        let xMean = x.reduce(0, +) / n
        let yMean = y.reduce(0, +) / n
        var numerator = 0.0
        var denominator = 0.0
        for i in 0..<x.count {
            numerator += (x[i] - xMean) * (y[i] - yMean)
            denominator += pow(x[i] - xMean, 2)
        }
        slope = numerator / denominator
        intercept = yMean - slope * xMean
    }
}
This code implements a linear regression algorithm that can be used for predicting a continuous output variable based on a set of input features. The algorithm calculates the slope and intercept of the line that best fits the input-output data, and then uses that line to make predictions for new input values.
To use this code, you would need to create an instance of the LinearRegression class, call the train() method with your input data and labels to fit the line, and then call the predict() method with a new input value to get its predicted output value.

