Certainly! Here's an implementation of the descendingSort() function in C++ that meets all the requirements you specified:
```c++
void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;
    int L[n1], R[n2];
    for (int i = 0; i < n1; i++)
        L[i] = arr[l + i];
    for (int j = 0; j < n2; j++)
        R[j] = arr[m + 1 + j];
    int i = 0;
    int j = 0;
    int k = l;
    while (i < n1 && j < n2) {
        if (L[i] >= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }
    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }
    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}
void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}
void descendingSort(int arr[], int n) {
    mergeSort(arr, 0, n - 1);
}
```
This implementation uses the merge sort algorithm to sort the array in descending order. The merge() function merges two subarrays of the array, while the mergeSort() function recursively divides the array into smaller subarrays until they can be sorted using the merge() function. Finally, the descendingSort() function calls mergeSort() with the appropriate parameters to sort the array in descending order.

